import{b as a}from"./chunk-EVVIIGGZ.js";import{h as r}from"./chunk-7X7OMDM6.js";import{f as n}from"./chunk-ZXNPHYPT.js";var d=[{title:"A respectful approach",text:"We treat everyone with respect and take the time you need. Whatever state your teeth are in, you can expect a discreet environment and professional care without judgment."},{title:"Modern equipment",text:"Top-tier technology for your comfort. We use modern diagnostic devices that let us provide the highest possible standard of dental care."},{title:"Transparent pricing",text:"You can find all our prices clearly listed on the website. You always know in advance what your insurance covers and what you may need to pay, before you sit down in the chair."}],c=[{name:"Preventive care and hygiene",text:"Regular check-ups and professional teeth cleaning that prevent bigger problems before they start. The foundation everything else is built on."},{name:"Cavity treatment",term:"restorative dentistry",text:"When a tooth needs a filling, we use a white material that blends with your smile. A procedure without unnecessary waiting, with care taken not to cause more discomfort than needed."},{name:"Root canal treatment",term:"endodontics",text:"When inflammation reaches the root of a tooth, we clean and treat the canal so the tooth can be saved whenever possible."},{name:"Gum care",term:"periodontology",text:"Healthy gums matter as much as healthy teeth. We treat inflammation and bleeding and provide preventive care, so you can be sure we're looking after you comprehensively."},{name:"Teeth whitening",term:"aesthetic dentistry",text:"Gentle, professional whitening under supervision, not blind home experiments. Results that last, with an approach that keeps your teeth safe."},{name:"Crowns and bridges",term:"prosthodontics",text:"When a tooth needs more than a filling, we replace the damaged or missing part with a crown or bridge, firm and functional, and as unnoticeable as possible."},{name:"Surgery and extractions",text:"From a simple tooth extraction to more complex procedures, always with anaesthesia and the calm approach you can expect at every stage of treatment."},{name:"Dental implants",term:"implantology",text:"A permanent replacement for a missing tooth that works and looks like your own. We will discuss with you whether an implant is the right choice for your situation."},{name:"X-ray and diagnostics",text:"A digital X-ray helps us see exactly what the eye cannot, quickly, with minimal exposure, and as part of almost every examination."},{name:"Dentures",term:"removable and fixed prosthetics",text:"Removable and fixed replacements for missing teeth that restore your smile's natural look and your mouth's everyday function. From a basic version to an upgraded solution, whichever suits you best."}],h=["Basic filling","Aesthetic filling, small extent","Root canal treatment, 1 canal","Crown (metal-ceramic)"].map(e=>{let o=r.flatMap(t=>t.items).find(t=>t.name===e);if(!o)throw new Error(`Missing preview price: ${e}`);return{name:e,price:o.price||"no co-payment"}}),p={heading:"Lead dentist and founder",text:"MUDr. Konstantinos Papadopoulos leads Dental Academy with a clear vision: to provide modern dental care that is not only highly professional but, above all, humane and gentle. His work is backed by years of practice and a focus on an individual approach to every patient.",todo:"PLACEHOLDER \u2014 years of practice, education and specialisation to be added by the dentist."},m=[{name:n.doctor,role:"Dentist",bio:"No one should be afraid to admit how long they've put off care. My job is to fix that, not to judge.",photo:a.doctor,todo:"PLACEHOLDER \u2014 quote awaiting confirmation by the dentist. Bio (education, practice, languages) not publicly available, to be added by the dentist."},{role:"Dental nurse",photo:a.nurse,todo:"PLACEHOLDER \u2014 name, photo and role to be provided by the client."}],u=[{title:"Welcome and conversation",text:"First, we'll talk about what's bothering you or what you'd like to address. No rush, no judgment."},{title:"Examination",text:"We'll look at the state of your teeth, and take an X-ray if needed, so we know where we stand."},{title:"Care plan",text:"We explain what we propose and why, including an indicative price, before we start anything."},{title:"Treatment or a follow-up appointment",text:"Depending on what's needed. Either right away, or we schedule a follow-up visit."}],y=[{quote:"I finally stopped being afraid to go to the dentist. The doctor is kind and calm, you feel safe with him, and the clinic is modern and pleasant.",author:"Jana H.",period:"7 months ago"},{quote:"A really nice approach to my son, a lovely modern clinic and a pleasant nurse. Speed, quality and price all check out.",author:"Jana D.",period:"a month ago"},{quote:"I was very afraid of root canal cleaning, but the procedure was gentle, painless and professional. The doctor has amazing patience with children.",author:"Tereza H.",period:"7 months ago"},{quote:"An honest and thorough approach, no unnecessary procedures. The clinic and waiting room are modern and clean.",author:"Luk\xE1\u0161 K.",period:"21 hours ago"}];export{d as a,c as b,h as c,p as d,m as e,u as f,y as g};
